{"command": "cat > /tmp/sensitivity_joint.py <<'PY'
import numpy as np
from scipy.optimize import least_squares
a=np.loadtxt('/root/data/tess_lc.txt',comments='#'); g=np.isfinite(a).all(1)&(a[:,2]==0)&(a[:,3]>0); a=a[g]; a=a[np.argsort(a[:,0])]; t=a[:,0]; f=a[:,1]; e=a[:,3]
cent=np.array([2146.86,2152.22,2162.94,2168.30]); nums=np.array([0,1,3,4])
def profile(x,W,q):
 ax=np.abs(x); h=W/2; ing=max(q*W,1e-8); flat=max(h-ing,0); p=np.zeros_like(ax); z=(ax>=flat)&(ax<h); p[z]=(h-ax[z])/ing; p[ax<flat]=1; return p
for rad in [.12,.15,.18,.20,.22,.25,.30]:
 for deg in [1,2,3]:
  idx=[]; ev=[]
  for j,c in enumerate(cent):
   q=np.where((t>c-rad)&(t<c+rad))[0]; idx.extend(q); ev.extend([j]*len(q))
  idx=np.asarray(idx); ev=np.asarray(ev); tt=t[idx]; yy=f[idx]; ee=e[idx]
  ncoef=deg+1
  def residual(v):
   P,t0,W,q,depth=v[:5]; co=v[5:].reshape(4,ncoef); x=tt-(t0+nums[ev]*P); z=x/rad; mod=np.empty_like(yy)
   for j in range(4):
    m=ev==j; base=sum(co[j,k]*z[m]**k for k in range(ncoef)); mod[m]=base-depth*profile(x[m],W,q)
   return (yy-mod)/ee
  v=np.zeros(5+4*ncoef); v[:5]=[5.3585,2146.86,.056,.05,.0025]
  for j,c in enumerate(cent):
   m=ev==j; z=(tt[m]-c)/rad; cf=np.polyfit(z,yy[m],deg,w=1/ee[m]); v[5+j*ncoef:5+(j+1)*ncoef]=cf[::-1]
  lo=[5.33,2146.82,.03,.01,0]+[-np.inf]*(4*ncoef); hi=[5.39,2146.90,.08,.8,.02]+[np.inf]*(4*ncoef)
  r=least_squares(residual,v,bounds=(lo,hi),loss='soft_l1',f_scale=1,max_nfev=1500,xtol=1e-12,ftol=1e-12,gtol=1e-12)
  print('rad %.2f deg %d P %.9f t0 %.8f W %.5f q %.3f depth %.6f cost %.1f'%(rad,deg,r.x[0],r.x[1],r.x[2],r.x[3],r.x[4],2*r.cost))
PY", "security_risk": "MEDIUM", "summary": "Create joint-fit sensitivity analysis script"}

