import numpy as np
from scipy.optimize import least_squares
a=np.loadtxt('/root/data/tess_lc.txt',comments='#'); g=np.isfinite(a).all(1)&(a[:,2]==0)&(a[:,3]>0); a=a[g]; a=a[np.argsort(a[:,0])]; t=a[:,0]; f=a[:,1]; e=a[:,3]
cent=np.array([2146.86,2152.22,2162.94,2168.30]); nums=np.array([0,1,3,4])
def prof(x,W,q):
 ax=np.abs(x); h=W/2; ing=q*W; flat=h-ing; p=np.zeros_like(ax); z=(ax>=flat)&(ax<h); p[z]=(h-ax[z])/ing; p[ax<flat]=1; return p
for rad in [.12,.15,.18,.2,.25]:
 for deg in [1,2,3]:
  idx=[]; ev=[]
  for j,c in enumerate(cent): q=np.where((t>c-rad)&(t<c+rad))[0]; idx+=list(q); ev += [j]*len(q)
  idx=np.array(idx);ev=np.array(ev);tt=t[idx];yy=f[idx];ee=e[idx]; nc=deg+1
  def fun(v):
   P,t0,W,q,d=v[:5]; co=v[5:].reshape(4,nc); x=tt-(t0+nums[ev]*P); z=x/rad; mod=np.empty_like(yy)
   for j in range(4):
    m=ev==j; mod[m]=sum(co[j,k]*z[m]**k for k in range(nc))-d*prof(x[m],W,q)
   return (yy-mod)/ee
  v=np.zeros(5+4*nc);v[:5]=[5.3592,2146.86,.043,.2,.002]
  for j,c in enumerate(cent):
   m=ev==j;z=(tt[m]-c)/rad;cf=np.polyfit(z,yy[m],deg,w=1/ee[m]);v[5+j*nc:5+(j+1)*nc]=cf[::-1]
  lo=[5.33,2146.82,.035,.10,0]+[-np.inf]*(4*nc);hi=[5.39,2146.90,.050,.8,.02]+[np.inf]*(4*nc)
  r=least_squares(fun,v,bounds=(lo,hi),loss='soft_l1',f_scale=1,max_nfev=1500,xtol=1e-12,ftol=1e-12,gtol=1e-12)
  print('rad',rad,'deg',deg,'P %.9f W %.6f q %.4f d %.6f cost %.1f'%(r.x[0],r.x[2],r.x[3],r.x[4],2*r.cost))
