  ii=np.array(ii);ev=np.array(ev);tt=t[ii];yy=f[ii];ee=e[ii];nc=deg+1
  def fun(v):
   P,t0,W,q=v[:4];depth=v[4:8];co=v[8:].reshape(4,nc);x=tt-(t0+nums[ev]*P);z=x/rad;mod=np.empty_like(yy)
   for j in range(4):
    m=ev==j;mod[m]=sum(co[j,k]*z[m]**k for k in range(nc))-depth[j]*prof(x[m],W,q)
   return (yy-mod)/ee
  v=np.zeros(8+4*nc);v[:4]=[5.3585,2146.86,.056,.05];v[4:8]=.0025
  for j,c in enumerate(cent):m=ev==j;z=(tt[m]-c)/rad;cf=np.polyfit(z,yy[m],deg,w=1/ee[m]);v[8+j*nc:8+(j+1)*nc]=cf[::-1]
  lo=[5.33,2146.82,.03,.01]+[0]*4+[-np.inf]*(4*nc);hi=[5.39,2146.90,.08,.8,.02]+[np.inf]*4+ [np.inf]*(4*nc)
  r=least_squares(fun,v,bounds=(lo,hi),loss='soft_l1',f_scale=1,max_nfev=1500,xtol=1e-12,ftol=1e-12,gtol=1e-12)
  print('rad',rad,'deg',deg,'P %.9f t0 %.8f W %.5f q %.3f depths %s cost %.1f'%(r.x[0],r.x[1],r.x[2],r.x[3],' '.join(f'{x:.5f}' for x in r.x[4:8]),2*r.cost))
